private function roundHalfUp(string $value, int $precision): string
{
    $multiplier = bcpow('10', (string)($precision + 1), self::SCALE);
    $scaled = bcmul($value, $multiplier, self::SCALE);

    // Check if the next digit is >= 5
    $nextDigit = substr($scaled, strpos($scaled, '.') + 1, 1);
    if ($nextDigit === false || (int)$nextDigit >= 5) {
        // Add 1 to the digit at $precision
        $precisionMultiplier = bcpow('10', (string)$precision, self::SCALE);
        $fraction = bcdiv($value, '1', self::SCALE); // dummy to keep scale

        // Simpler way to do half up with bcmath:
        // add 0.0000005 then truncate
    }

    // Let's use a more robust BCMath roundHalfUp implementation
    $shift = bcpow('10', (string)$precision);
    $shifted = bcmul($value, $shift, self::SCALE);
    $rounded = bcadd($shifted, '0.5', self::SCALE);
    $truncated = bcdiv($rounded, '1', 0);

    return bcdiv($truncated, $shift, $precision);
}

